namespace KotW.Shared;

// People, quests and the storyline.
//
// THE SHATTERED WIND. For a thousand years the Wind Pearl rested in the Sky Palace above
// Cloudgate and kept the four winds turning: rain in spring, storms in summer, the harvest wind,
// the snow. Twelve winters ago the royal astrologer Heuk-un, "Black Cloud", climbed the Stair to
// Heaven and tried to drink the Pearl's power. It shattered. Its shards fell into the great
// guardian spirits of the land and drove them mad: the mountain tiger, the serpent of the Dragon
// King's shrine, the iron-eater of the highlands, the White Tiger of the west, the nine-tailed fox,
// the judge of the dead and the thunder roc. Now Heuk-un's cult, the Black Cloud, hunts the shards
// so he can finish what he began and become the wind itself. The player follows the shards from
// Pungseong to the Eye of the Winds and brings all eight home.
public static partial class Content
{
    private static int Xp(int level, double k) => (int)Math.Round(Rules.ExpToNext(level) * k);
    private static int Gp(int level, double k = 1) => (int)Math.Round(level * 25 * k);

    // services: rest | shop:<id> | storage | revive | job:<class>
