        new NpcDef { Id = "malsun", Name = "Reed-Cutter Mal-sun", Map = "marsh", X = 22, Y = 6, Look = new("#c89068", "#4a3020", "bun", "npc_fisher", null, "straw_hat"), Services = new[] { "shop:camp", "revive" },
