            Outro = "The dead thank you. Most of them. One of them is complaining about the cold, but that one always complains.", RewardExp = Xp(39, 0.45), RewardGold = Gp(39) },
        new QuestDef { Id = "h_ghosts", Giver = "mudang", Level = 41, Title = "Weeping Water", BringItem = "ghost_veil", Count = 8,
            Text = "Mul-gwisin, water ghosts, are drowned souls that won't let go. Their veils are what's left of their grief. Bring me eight; I'll burn them with the right words.",
            Outro = "Smell that? Salt and incense. Eight souls went to their rest just now.", RewardExp = Xp(41, 0.45), RewardGold = Gp(41), RewardItems = new[] { ("rain_hat", 1) } },
        new QuestDef { Id = "s_imugi", Giver = "mudang", Level = 42, Requires = "s_coral", Story = true, Title = "The Serpent Who Was Never a Dragon", KillMonster = "imugi", Count = 1,
            Text = "An imugi is a serpent that waited a thousand years to become a dragon and was refused. This one swallowed a shard of the Wind Pearl and thinks it is finally a dragon. It coils in the deepest chamber of the shrine. End its waiting.",
            Outro = "I felt it go. The sea is breathing again. And you've a second shard. The spirits are whispering one word over and over now: Cloudgate.",
            RewardExp = Xp(42, 1.0), RewardGold = Gp(42, 3), RewardItems = new[] { ("cloudgate_scroll", 2) } },
        new QuestDef { Id = "s_north", Giver = "mudang", TurnIn = "abbot", Level = 44, Requires = "s_imugi", Story = true, Title = "Smoke in the North",
            Text = "The Black Cloud has gone north, through the Cinder Highlands, to Cloudgate Monastery at the foot of the Stair to Heaven. Go through the north gate and over the ash. Tell Abbot Hyeon-gak what you carry. Your spirits go with you. Mine stay here; they hate the cold.",
            Outro = "Two shards of the Wind Pearl, carried by one traveller. I have prayed twelve years to see this. Sit, eat, and then I will tell you what we failed to stop.",
            RewardExp = Xp(44, 0.6), RewardGold = Gp(44) },

        // ======== Chapter 3: Cinder Highlands, Cloudgate and Frostfang Pass (44-66) ========
        new QuestDef { Id = "c_tusks", Giver = "miner", Level = 46, Title = "Ash Boars in the Shafts", KillMonster = "ash_boar", Count = 14,
            Text = "The ash boars dig into our shafts for the warm rock. They've collapsed two already. Fourteen fewer and we can dig again.",
            Outro = "The shafts are quiet. My men send their thanks, and the last of the good tonic.", RewardExp = Xp(46, 0.45), RewardGold = Gp(46), RewardItems = new[] { ("wild_ginseng", 6) } },
        new QuestDef { Id = "s_ash", Giver = "abbot", Level = 48, Requires = "s_north", Story = true, Title = "Ash on the Wind", KillMonster = "cultist", Count = 12,
            Text = "Twelve years ago Heuk-un passed through our gate as a guest. We let him climb. Now his cult camps in the Cinder Highlands, feeding iron to something in the crater. Scatter them: twelve cultists.",
            Outro = "They carried bells. Our bells, stolen from the belfry, melted for feed. Whatever eats iron in that crater has eaten our prayers too.",
            RewardExp = Xp(48, 0.7), RewardGold = Gp(48, 1.5), RewardItems = new[] { ("lotus_dew", 6) } },
        new QuestDef { Id = "c_horns", Giver = "miner", Level = 49, Title = "Horns That Burn", BringItem = "fire_horn", Count = 8,
            Text = "Fire dokkaebi horns burn for a week without wood. Eight of those and the camp will be warm until spring.",
            Outro = "Warm hands at last! Take this, it was my father's.", RewardExp = Xp(49, 0.45), RewardGold = Gp(49), RewardItems = new[] { ("ember_ring", 1) } },
        new QuestDef { Id = "c_bats", Giver = "brother_jin", Level = 50, Title = "Embers in the Belfry", KillMonster = "ember_bat", Count = 15,
            Text = "With the bells gone, ember bats have nested in the empty belfry and the highland cliffs. They set the roof thatch alight twice this month. Fifteen, please, before the third time.",
            Outro = "The belfry is dark and quiet. One day it will ring again.", RewardExp = Xp(50, 0.45), RewardGold = Gp(50), RewardItems = new[] { ("wild_ginseng", 5), ("lotus_dew", 5) } },
        new QuestDef { Id = "s_bulgasari", Giver = "abbot", Level = 52, Requires = "s_ash", Story = true, Title = "The Iron-Eater", KillMonster = "bulgasari", Count = 1,
            Text = "Bulgasari: a beast of the old stories that grows by eating iron and cannot be killed by it. The cult fed it a shard and our bells. It lies in the crater in the north-east of the highlands. Strike with spirit, not just steel.",
            Outro = "The third shard. And the bells: you brought back the clapper of the great bell, still warm. Brother Jin is weeping. So am I.",
            RewardExp = Xp(52, 1.0), RewardGold = Gp(52, 3) },
        new QuestDef { Id = "c_cores", Giver = "monk_smith", Level = 52, Title = "A Heart of Magma", BringItem = "magma_core", Count = 6,
            Text = "To cast a new great bell I need a fire hotter than coal. Lava golem cores burn hot enough. Six of them.",
            Outro = "The mould is ready. When this bell rings, the whole valley will hear it.", RewardExp = Xp(52, 0.45), RewardGold = Gp(52), RewardItems = new[] { ("dragon_helm", 1) } },
        new QuestDef { Id = "s_pass", Giver = "abbot", TurnIn = "ranger", Level = 56, Requires = "s_bulgasari", Story = true, Title = "The Frozen Pass",
            Text = "Our ranger, Seol-hwa, watches Frostfang Pass east of the monastery. She sent word: the White Tiger of the West has come down from the peaks, and men in black masks walk with it unharmed. Go to her.",
            Outro = "The Abbot's sent help at last. Good. You'll want to stand by the fire for a while; your eyebrows are frozen.",
            RewardExp = Xp(56, 0.6), RewardGold = Gp(56) },
        new QuestDef { Id = "f_wolves", Giver = "ranger", Level = 57, Title = "The Pack Leader's Due", KillMonster = "snow_wolf", Count = 15,
            Text = "The snow wolves follow the White Tiger like crows follow an army. Thin the pack: fifteen.",
            Outro = "Fewer howls tonight. I might even sleep.", RewardExp = Xp(57, 0.45), RewardGold = Gp(57), RewardItems = new[] { ("wild_ginseng", 6) } },
        new QuestDef { Id = "s_adepts", Giver = "ranger", Level = 60, Requires = "s_pass", Story = true, Title = "Footprints in the Snow", KillMonster = "cult_adept", Count = 12,
            Text = "The Black Cloud adepts chant over the White Tiger every dusk, keeping the shard's madness hot. Twelve of them, and the tiger will be alone.",
            Outro = "They had maps. Of the Sky Palace. And a list of names: the tiger, the fox, the judge of the dead. They're going after every shard, in order. We have to stay ahead of them.",
            RewardExp = Xp(60, 0.7), RewardGold = Gp(60, 1.5), RewardItems = new[] { ("snowfox_cap", 1) } },
        new QuestDef { Id = "f_dokkaebi", Giver = "herb_monk", Level = 61, Title = "Frost Horns", KillMonster = "ice_dokkaebi", Count = 15,
            Text = "Ice dokkaebi raid our herb terraces in the pass for the frost-moss. Chase fifteen of them back to the peaks, please.",
            Outro = "The terraces are safe. Here, peaches for your trouble.", RewardExp = Xp(61, 0.45), RewardGold = Gp(61), RewardItems = new[] { ("heavenly_peach", 4) } },
        new QuestDef { Id = "f_cores", Giver = "ranger", Level = 62, Title = "Cold Hearts", BringItem = "ice_core", Count = 8,
            Text = "Ice golem cores keep meat fresh all summer, and the monastery has many mouths. Eight cores.",
            Outro = "Cold as a debt collector's heart. Perfect.", RewardExp = Xp(62, 0.45), RewardGold = Gp(62), RewardItems = new[] { ("frost_ring", 1) } },
        new QuestDef { Id = "s_baekho", Giver = "ranger", Level = 63, Requires = "s_adepts", Story = true, Title = "The White Tiger of the West", KillMonster = "white_tiger", Count = 1,
            Text = "Baekho, the White Tiger, guardian of the west wind. A shard sits in its chest like a splinter of ice. It waits in the clearing at the north-east end of the pass. Free it.",
            Outro = "The fourth shard. And the snow is falling straight down for the first time in twelve years, not sideways. The west wind is resting.",
            RewardExp = Xp(63, 1.0), RewardGold = Gp(63, 3) },

        // ======== Chapter 4: The Moonlit Grove and the Yellow Springs (65-86) ========
        new QuestDef { Id = "s_moon", Giver = "ranger", TurnIn = "wolhwa", Level = 66, Requires = "s_baekho", Story = true, Title = "Moonlight and Lies",
            Text = "The cult's list said 'the fox' next. West of Cloudgate is the Moonlit Bamboo Grove, where foxes are older than the monastery. Something there has been sending me notes tied to arrows. Signed 'Wol-hwa'. Go and see.",
            Outro = "You came. Good. I am Wol-hwa. The gumiho in my grove is my elder sister. She swallowed a shard to save the grove from the Black Cloud, and it ate her instead.",
            RewardExp = Xp(66, 0.6), RewardGold = Gp(66) },
        new QuestDef { Id = "b_rabbits", Giver = "wolhwa", Level = 67, Title = "Rice Cakes for the Moon", BringItem = "moon_fur", Count = 10,
            Text = "The moon rabbits pound rice cakes for the moon every night, and my sister has stopped letting them. Bring me ten tufts of moon rabbit fur; I'll weave a charm to keep them safe from her.",
            Outro = "Soft as clouds. The rabbits will be pounding again by the full moon.", RewardExp = Xp(67, 0.45), RewardGold = Gp(67), RewardItems = new[] { ("heavenly_peach", 5) } },
        new QuestDef { Id = "s_maidens", Giver = "wolhwa", Level = 70, Requires = "s_moon", Story = true, Title = "Sisters of the Grove", KillMonster = "fox_maiden", Count = 12,
            Text = "My sister has woken our younger sisters into fox maidens: beautiful, hungry and not themselves. Twelve of them guard her. I cannot raise a hand to my own blood. You can.",
            Outro = "They're foxes again, small and frightened and running home. Thank you. Now only she remains.",
            RewardExp = Xp(70, 0.7), RewardGold = Gp(70, 1.5), RewardItems = new[] { ("night_hood", 1) } },
        new QuestDef { Id = "b_eggs", Giver = "wolhwa", Level = 71, Title = "Faces Without Faces", KillMonster = "egg_ghost", Count = 15,
            Text = "Dalgyal gwisin, egg ghosts: souls so forgotten they lost their faces. The shard's song draws them to the grove. Fifteen. Don't look too long at where their faces should be.",
            Outro = "I hope someone, somewhere, remembers their names.", RewardExp = Xp(71, 0.45), RewardGold = Gp(71), RewardItems = new[] { ("starlight_nectar", 5) } },
        new QuestDef { Id = "s_gumiho", Giver = "wolhwa", Level = 74, Requires = "s_maidens", Story = true, Title = "Nine Tails", KillMonster = "gumiho", Count = 1,
            Text = "My sister waits in the south-west of the grove, by the old moon pool. Nine tails, and every one of them a lie. If you can strike the shard from her, she may live as a fox again. Please.",
            Outro = "She's... sleeping. One tail. My sister. And the fifth shard, warm from her heart. Take it far from here, before it sings to anyone else.",
            RewardExp = Xp(74, 1.0), RewardGold = Gp(74, 3) },
        new QuestDef { Id = "s_springs", Giver = "wolhwa", TurnIn = "ferryman", Level = 76, Requires = "s_gumiho", Story = true, Title = "The Yellow Springs",
            Text = "At the north edge of the grove the bamboo grows black and the path goes down. It is the Road of the Yellow Springs, where the dead walk to judgment. The cult's list said 'the judge' next. The ferryman at the road's mouth owes me a favour.",
            Outro = "Wol-hwa's friend, eh? She won a bet with me four hundred years ago. Fine. I'll keep you breathing, mostly.",
            RewardExp = Xp(76, 0.6), RewardGold = Gp(76) },
        new QuestDef { Id = "u_rats", Giver = "ferryman", Level = 77, Title = "Gnawers of the Dead", KillMonster = "plague_rat", Count = 18,
            Text = "Grave rats gnaw on the dead as they walk to judgment. It's undignified. Eighteen.",
            Outro = "The dead walk whole again. They won't thank you; they're busy.", RewardExp = Xp(77, 0.45), RewardGold = Gp(77) },
        new QuestDef { Id = "s_lanterns", Giver = "ferryman", Level = 79, Requires = "s_springs", Story = true, Title = "Lanterns for the Lost", BringItem = "lantern_shard", Count = 10,
            Text = "Every soul carries a lantern to the Judge. Since the shard came, the lanterns have broken loose and float about as wisps, and the dead wander lost. Ten lantern shards and I can light the road again.",
            Outro = "The road is lit. And look how the lights all lean north, toward the Judge's court. The shard is there, as you feared.",
            RewardExp = Xp(79, 0.7), RewardGold = Gp(79, 1.5), RewardItems = new[] { ("starlight_nectar", 8) } },
        new QuestDef { Id = "u_dust", Giver = "ferryman", Level = 80, Title = "Ashes to Ashes", BringItem = "bone_dust", Count = 12,
            Text = "Bone dust, from the rats and the ghost soldiers. Mixed with river water it makes the ink the Judge writes verdicts in. He's going to need a lot of ink when this is over.",
            Outro = "Enough ink for a thousand sins. Most of them yours, probably.", RewardExp = Xp(80, 0.45), RewardGold = Gp(80), RewardItems = new[] { ("heavenly_peach", 6) } },
        new QuestDef { Id = "s_reapers", Giver = "ferryman", Level = 82, Requires = "s_lanterns", Story = true, Title = "Reapers Without a King", KillMonster = "reaper", Count = 12,
            Text = "The jeoseung saja, the reapers who walk the dead to judgment, serve whoever holds the Judge's seal, and the shard holds it now. They've started collecting the living. Twelve reapers, sent back to the river.",
            Outro = "Twelve fewer black hats on my road. The Judge is alone in his court now. Alone and mad.",
            RewardExp = Xp(82, 0.7), RewardGold = Gp(82, 1.5) },
        new QuestDef { Id = "s_judge", Giver = "ferryman", Level = 84, Requires = "s_reapers", Story = true, Title = "The Lantern Judge", KillMonster = "lantern_judge", Count = 1,
            Text = "The Lantern Judge has weighed every soul for three thousand years. With a shard in his heart he finds them all guilty. His court is at the north end of the road. Overturn the verdict.",
            Outro = "The scales are still. The sixth shard. Do you know what he said as the shard came loose? 'Tell the astrologer his sentence is waiting.' Even the dead are on your side now.",
            RewardExp = Xp(84, 1.0), RewardGold = Gp(84, 3) },
        new QuestDef { Id = "u_tea", Giver = "herb_monk", Level = 84, Title = "Tea for the Weary", BringItem = "fox_hair", Count = 10,
            Text = "Fox hair steeped in pine tea is an old remedy for grief, and the monastery is full of grieving people. Ten strands of silver fox hair from the grove.",
            Outro = "The brothers will sleep tonight. So should you.", RewardExp = Xp(84, 0.4), RewardGold = Gp(84), RewardItems = new[] { ("starlight_nectar", 6), ("heavenly_peach", 6) } },

        // ======== Chapter 5: The Sky Palace and the Eye of the Winds (85-100) ========
        new QuestDef { Id = "s_ascent", Giver = "ferryman", TurnIn = "envoy", Level = 86, Requires = "s_judge", Story = true, Title = "The Stair to Heaven",
            Text = "Six shards. The other two are above: the Thunder Roc that nests in the Sky Palace, and the one who started it all. Go back to Cloudgate and through its north gate, up the Stair to Heaven. Somebody up there is still waiting for help.",
            Outro = "Six shards of the Pearl, in a mortal's pack. The envoys argued for twelve years about whether to ask the earth for help. I am glad someone stopped arguing.",
            RewardExp = Xp(86, 0.6), RewardGold = Gp(86) },
        new QuestDef { Id = "k_feathers", Giver = "envoy", Level = 88, Title = "Feathers of Thunder", BringItem = "crane_feather", Count = 10,
            Text = "The thunder cranes nest in the palace ruins now. Their feathers hold lightning. Ten, and I can weave a ward for the last gate.",
            Outro = "It crackles! Good. The ward will hold.", RewardExp = Xp(88, 0.45), RewardGold = Gp(88), RewardItems = new[] { ("heavenly_peach", 8) } },
        new QuestDef { Id = "s_guards", Giver = "envoy", Level = 89, Requires = "s_ascent", Story = true, Title = "Guardians Bewitched", KillMonster = "heavenly_guard", Count = 12,
            Text = "The palace guards swore to protect the Pearl. Heuk-un turned their oath inside out: now they protect his storm. Twelve of them stand between us and the throne hall. Free them.",
            Outro = "Their armour is empty. They've gone home to the stars. I'll light incense for each of them.",
            RewardExp = Xp(89, 0.7), RewardGold = Gp(89, 1.5), RewardItems = new[] { ("celestial_helm", 1) } },
        new QuestDef { Id = "k_haetae", Giver = "envoy", Level = 91, Title = "Stone Lions Awake", KillMonster = "haetae", Count = 14,
            Text = "The haetae statues judge right from wrong. Heuk-un's storm convinced them we are the wrong. Fourteen of them must go back to being stone.",
            Outro = "Still and silent. I almost miss their grumbling.", RewardExp = Xp(91, 0.45), RewardGold = Gp(91) },
        new QuestDef { Id = "s_roc", Giver = "envoy", Level = 93, Requires = "s_guards", Story = true, Title = "Storm Over the Palace", KillMonster = "thunder_roc", Count = 1,
            Text = "The Thunder Roc carried the Pearl's storms across the sky for a thousand years. Now it carries Heuk-un's. It nests on the throne hall, at the north of the ruins. Bring it down.",
            Outro = "Seven shards. The roc is a bird again, a very large and very confused one. Through the gate behind the throne hall is the Eye of the Winds. He's there. He's been there all along.",
            RewardExp = Xp(93, 1.0), RewardGold = Gp(93, 3), RewardItems = new[] { ("roc_feather", 1) } },
        new QuestDef { Id = "e_wraiths", Giver = "envoy", Level = 97, Title = "The Last Storm", KillMonster = "storm_wraith", Count = 18,
            Text = "Storm wraiths: Black Cloud cultists who gave their bodies to the wind. They swarm the Eye. Eighteen fewer, and Heuk-un fights alone.",
            Outro = "The storm is thinner. Can you feel it? Blue sky at the edges.", RewardExp = Xp(97, 0.45), RewardGold = Gp(97) },
        new QuestDef { Id = "s_eye", Giver = "envoy", Level = 96, Requires = "s_roc", Story = true, Title = "The Eye of the Winds", KillMonster = "heuk_un", Count = 1,
            Text = "Heuk-un holds the last shard in the heart of the storm, and believes that if he gathers the rest he will become the wind itself. He will try to take yours. End it, and the Pearl can be whole.",
            Outro = "It's over. The storm is just weather now. And the eighth shard: the one he swallowed first, twelve years ago. Gather all eight and take them home, hero. Home is where this story should end.",
            RewardExp = Xp(96, 1.5), RewardGold = Gp(96, 5), RewardItems = new[] { ("four_winds_ring", 1) } },
        new QuestDef { Id = "s_home", Giver = "envoy", TurnIn = "elder", Level = 96, Requires = "s_eye", Story = true, Title = "The Wind Returns", BringItem = "pearl_shard", Count = 8,
            Text = "Eight shards: the Mountain Lord, the imugi, Bulgasari, Baekho, the gumiho, the Judge, the roc and Heuk-un himself. Bring them all to Elder Baek in Pungseong, where your journey began. The Pearl should be mended by the people it protects.",
            Outro = "Eight... and they're pulling together in my hands. Look! Look at the weathervane! It's turning! Do you feel that? That's the east wind. That's spring. Child, you brought the wind home.",
            RewardExp = Xp(96, 2.0), RewardGold = 50000, RewardItems = new[] { ("heart_of_winds", 1) } },

        // ======== Class trials (unlock the advanced class at level 50) ========
        new QuestDef { Id = "t_warrior", Giver = "m_warrior", Level = 48, Cls = "warrior", Title = "Trial of the General", KillMonster = "lava_golem", Count = 12,
            Text = "A Warlord breaks what cannot be broken. In the Cinder Highlands walk golems of living lava. Break twelve with your own hands. Then come back at level 50 and I'll make you a general.",
            Outro = "Twelve golems, and your arms still attached. You're ready.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
        new QuestDef { Id = "t_rogue", Giver = "m_rogue", Level = 48, Cls = "rogue", Title = "Trial of Shadows", BringItem = "cult_sigil", Count = 10,
            Text = "A Shadowblade takes what others guard with their lives. The Black Cloud cultists carry sigils sewn into their robes. Steal ten. Come back at level 50.",
            Outro = "Ten sigils, and not one cultist saw your face. Perfect.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
        new QuestDef { Id = "t_mystic", Giver = "m_mystic", Level = 48, Cls = "mystic", Title = "Trial of Flame", BringItem = "magma_core", Count = 8,
            Text = "A Stormcaller holds the fire of the earth without flinching. Bring me eight magma cores from the lava golems of the highlands. Then, at level 50, the storm is yours.",
            Outro = "Still warm. You held these all the way here? Good.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
        new QuestDef { Id = "t_monk", Giver = "m_monk", Level = 48, Cls = "monk", Title = "Trial of Mercy", KillMonster = "drowned_sailor", Count = 25,
            Text = "A Lotus Saint brings peace to those who cannot find it. The drowned sailors of the Saltwind Coast walk without rest. Send twenty-five of them home. Return at level 50.",
            Outro = "Twenty-five souls at rest. The lotus opens for you.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
        new QuestDef { Id = "t_hunter", Giver = "m_hunter", Level = 48, Cls = "hunter", Title = "Trial of the Hawk", BringItem = "ember_wing", Count = 10,
            Text = "A Windstrider never misses. Ember bats in the highlands fly faster than any hawk. Ten wings, shot clean. Back here at level 50.",
            Outro = "Not a single wing torn by a second arrow. Good shooting.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
        new QuestDef { Id = "t_shaman", Giver = "m_shaman", Level = 48, Cls = "shaman", Title = "Trial of Spirits", KillMonster = "water_ghost", Count = 20,
            Text = "A Grand Shaman commands the dead, not the other way around. The mul-gwisin of the drowned shrine are the angriest dead in the kingdom. Put twenty of them in their place. Return at level 50.",
            Outro = "The water ghosts speak of you with respect. And a little fear. Good.", RewardExp = Xp(48, 0.6), RewardGold = Gp(48) },
    }.ToDictionary(q => q.Id);

